package org.mockito.internal.util.reflection;

import java.io.*;
import java.lang.reflect.Field;
import java.lang.reflect.ParameterizedType;
import java.lang.reflect.Type;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class GenericMaster_getGenericType_TriageGen2Test {

    private final GenericMaster genericMaster = new GenericMaster();

    @Test
    public void testGetGenericType_WithParameterizedType() throws NoSuchFieldException {
        // Test case: Field is List<String>
        Field field = TestClass.class.getDeclaredField("stringList");

        Class<?> result = genericMaster.getGenericType(field);

        assertEquals(String.class, result);
    }







    /**
     * Helper class to provide fields for reflection testing
     */
    private static class TestClass {
        public java.util.List<String> stringList;
        public String simpleString;
        public java.util.List rawList;
    }
}

